    text?: string;
    /** Snippet to display (for direct props). */
    snippet?: Snippet;
    /** Render function to display (for object literals - avoids Svelte 5 snippet typing issues). */
    render?: RenderFn;
    /** Component to display. */
    component?: Component;
    /** Keyboard shortcut to display next to the item. */
